from flask import Flask, request, render_template, jsonify

app = Flask(__name__)

@app.route("/car", methods=["POST"])
def car():
    # Unsanitized user input from form fields
    make = request.form["make"]
    model = request.form["model"]
    year = request.form["year"]

    # XSS vulnerability: User input is directly embedded in HTML via Jinja2 template
    return render_template("car.html", make=make, model=model, year=year)
